{
  "name": "llm_scan_pdu_cfg",
  "confidence": "medium",
  "docstring": "Configures a BLE link-layer scan PDU descriptor from its type-specific configuration table, then schedules, enables, or updates its RX/status state.",
  "subsystem": "ble",
  "var_renames": {
    "a1": "pdu_desc",
    "a2": "pdu_type",
    "v4": "cfg_base",
    "v5": "cfg_entry",
    "v6": "irq_lock_ptr",
    "v16": "pdu_queue_ptr",
    "v20": "target_idx",
    "v21": "llm_ctx_base",
    "v22": "pdu_link_node"
  },
  "struct_hints": [
    {
      "offset": 14,
      "meaning": "byte PDU type assigned from a2"
    },
    {
      "offset": 16,
      "meaning": "byte target/connection index; 0xFF indicates invalid or no target"
    },
    {
      "offset": 28,
      "meaning": "pointer to PDU queue/list node or packet buffer reference"
    },
    {
      "offset": 32,
      "meaning": "parent packet descriptor; its +64 field holds status bits"
    },
    {
      "offset": 38,
      "meaning": "uint16 PDU status/flag word"
    },
    {
      "offset": 53,
      "meaning": "byte PDU active or enabled flag"
    }
  ]
}
